import{supabase as l}from"./supabase-DUkCiNAm.js";/* empty css              */document.getElementById("login-form").addEventListener("submit",async a=>{a.preventDefault();let n=document.getElementById("email").value.trim();n.includes("@")||(n+="@automatizap.com");const r=document.getElementById("password").value,o=document.getElementById("login-error"),t=document.querySelector(".login-btn");t.textContent="Entrando...",t.disabled=!0,o.style.display="none";const{data:m,error:s}=await l.auth.signInWithPassword({email:n,password:r});if(s){t.textContent="Entrar",t.disabled=!1,o.textContent="Erro do Banco: "+s.message,o.style.display="block";const e=document.querySelector(".login-form-container");e.style.transform="translateX(-10px)",setTimeout(()=>e.style.transform="translateX(10px)",100),setTimeout(()=>e.style.transform="translateX(-10px)",200),setTimeout(()=>e.style.transform="translateX(0)",300)}else window.location.href="index.html"});
